SELECT r.id AS id, r.task_step_id AS taskStepId, r.attempt_no AS attemptNo, r.status AS status, r.machine_ip AS machineIp, r.start_time AS startTime, r.end_time AS endTime, r.duration_ms AS durationMs, r.exit_code AS exitCode, r.fail_reason AS failReason FROM task_step_retry r WHERE r.task_step_id IN
#{id}
ORDER BY r.task_step_id, r.attempt_no
